import{_ as e,o as i,c as o,a2 as n}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"Las Normas Éticas Transplanar","description":"","frontmatter":{},"headers":[],"relativePath":"es/88-跨位面伦理准则.md","filePath":"es/88-跨位面伦理准则.md"}'),s={name:"es/88-跨位面伦理准则.md"};function r(t,a,c,l,d,u){return i(),o("div",null,[...a[0]||(a[0]=[n('<h1 id="las-normas-eticas-transplanar" tabindex="-1">Las Normas Éticas Transplanar <a class="header-anchor" href="#las-normas-eticas-transplanar" aria-label="Permalink to &quot;Las Normas Éticas Transplanar&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Elemento</th><th>Contenido</th></tr></thead><tbody><tr><td>N.º de documento</td><td>88</td></tr><tr><td>Módulo</td><td>Interacción Transplanar y Reglas Temporales</td></tr><tr><td>Palabras clave</td><td>ética transplanar, subjetividad civilizacional, no interferencia, respeto cultural, diplomacia simbiótica</td></tr></tbody></table><h2 id="i-el-fundamento-filosofico-de-las-normas-eticas" tabindex="-1">I. El Fundamento Filosófico de las Normas Éticas <a class="header-anchor" href="#i-el-fundamento-filosofico-de-las-normas-eticas" aria-label="Permalink to &quot;I. El Fundamento Filosófico de las Normas Éticas&quot;">​</a></h2><p>Las Normas Éticas Transplanar son las normas morales y códigos de conducta que la Civilización Simbiótica del Ancla debe seguir al interactuar con civilizaciones de otros planos. Su fundamento filosófico es el principio de &quot;subjetividad civilizacional&quot;: toda civilización de todo plano, sin importar su nivel de desarrollo, forma racial o sistema social, posee una subjetividad inalienable y el derecho al desarrollo autónomo. Ninguna civilización extranjera puede privar de esa subjetividad por ningún motivo, ni imponer su propia voluntad a otras civilizaciones.</p><p>El establecimiento de este fundamento filosófico está en la misma línea que el concepto central &quot;antidepredación&quot; de la Civilización Simbiótica del Ancla. La característica esencial de una civilización depredadora es no reconocer la subjetividad de otras civilizaciones, tratándolas como recursos explotables u objetos a conquistar. Para que la Civilización Simbiótica del Ancla supere verdaderamente a las civilizaciones depredadoras, debe abandonar por completo esa mentalidad en la interacción transplanar, tratando a toda civilización que encuentre con igualdad, respeto y simbiosis.</p><p>El ámbito de aplicación de las Normas Éticas Transplanar cubre todos los comportamientos de interacción transplanar, incluyendo sin limitarse a: travesía entre planos, comunicación transplanar, actividades arqueológicas, intercambios comerciales, intercambios culturales, cooperación técnica e intervención humanitaria en situaciones de emergencia. Toda organización e individuo que realice una interacción transplanar debe cumplir todas las disposiciones de estas normas.</p><h2 id="ii-los-seis-principios-eticos" tabindex="-1">II. Los Seis Principios Éticos <a class="header-anchor" href="#ii-los-seis-principios-eticos" aria-label="Permalink to &quot;II. Los Seis Principios Éticos&quot;">​</a></h2><p>Las Normas Éticas Transplanar se componen de seis principios fundamentales, formando un sistema completo de valores éticos:</p><table tabindex="0"><thead><tr><th>Principio</th><th>Connotación central</th><th>Requisitos específicos</th></tr></thead><tbody><tr><td>Principio de Autonomía Civilizacional</td><td>Respetar el derecho al desarrollo autónomo de la civilización del plano objetivo, no interferir forzosamente en sus asuntos internos</td><td>No cambiar por la fuerza el sistema social, la ideología y la vía de desarrollo de la civilización objetivo; no cultivar agentes o regímenes títeres dentro de la civilización objetivo</td></tr><tr><td>Principio de No Interferencia</td><td>Salvo que la civilización objetivo enfrente una crisis de nivel de extinción y solicite activamente ayuda, no se realiza ninguna interferencia sustancial</td><td>No intervenir en los conflictos internos de la civilización objetivo; no proporcionar armas o ayuda militar a ninguna de las partes de la civilización objetivo; no manipular la opinión pública y los procesos políticos de la civilización objetivo</td></tr><tr><td>Principio de Respeto Cultural</td><td>Respetar las tradiciones culturales, creencias religiosas y costumbres de la civilización objetivo</td><td>No emitir evaluaciones discriminatorias o burlas maliciosas sobre la cultura de la civilización objetivo; no imponer por la fuerza los productos culturales y valores del propio plano; no realizar asimilación cultural en nombre de la &quot;civilización&quot;</td></tr><tr><td>Principio de Igualdad y Beneficio Mutuo</td><td>Las relaciones transplanar deben basarse en la igualdad, asegurando que ambas partes se beneficien de la relación</td><td>No utilizar ventajas tecnológicas para un comercio desigual; no saquear los recursos de la civilización objetivo; la exportación de tecnología debe considerar la capacidad de aceptación y el impacto social de la civilización objetivo</td></tr><tr><td>Principio de Impacto Mínimo</td><td>La interacción transplanar debe reducir al mínimo posible el impacto externo sobre la civilización objetivo</td><td>Priorizar métodos de interacción de bajo contacto y baja interferencia; el alcance e intensidad de las actividades de interacción deben controlarse estrictamente dentro de los límites necesarios; tras finalizar la interacción, evaluar y eliminar los impactos residuales innecesarios</td></tr><tr><td>Principio de Rendición de Cuentas</td><td>Todos los comportamientos de interacción transplanar deben ser trazables, supervisables y responsables</td><td>Establecer archivos y registros de interacción completos; crear una institución independiente de supervisión ética; investigar y sancionar los comportamientos que violen las normas éticas</td></tr></tbody></table><p>Existe una conexión lógica intrínseca entre los seis principios: el Principio de Autonomía Civilizacional es el valor fundamental, el Principio de No Interferencia es el requisito central, el Principio de Respeto Cultural es la manifestación a nivel cultural, el Principio de Igualdad y Beneficio Mutuo es la garantía a nivel económico, el Principio de Impacto Mínimo es la norma a nivel operativo y el Principio de Rendición de Cuentas es la restricción a nivel institucional. Los seis constituyen juntos un circuito ético completo de &quot;valor — requisito — manifestación — garantía — norma — restricción&quot;.</p><h2 id="iii-normas-eticas-para-diferentes-escenarios-de-interaccion" tabindex="-1">III. Normas Éticas para Diferentes Escenarios de Interacción <a class="header-anchor" href="#iii-normas-eticas-para-diferentes-escenarios-de-interaccion" aria-label="Permalink to &quot;III. Normas Éticas para Diferentes Escenarios de Interacción&quot;">​</a></h2><h3 id="_3-1-normas-eticas-para-el-escenario-arqueologico" tabindex="-1">3.1 Normas Éticas para el Escenario Arqueológico <a class="header-anchor" href="#_3-1-normas-eticas-para-el-escenario-arqueologico" aria-label="Permalink to &quot;3.1 Normas Éticas para el Escenario Arqueológico&quot;">​</a></h3><p>La arqueología transplanar es uno de los escenarios de interacción más comunes, y el núcleo de sus normas éticas es el &quot;no molestar&quot;. El equipo arqueológico debe seguir estrictamente el esquema estándar de Espejo de Réplica + Espacio Aislado + Retorno de Solo Conocimiento, asegurando que el proceso arqueológico no sea percibido por la civilización objetivo. Para los planos donde aún existe una civilización viva, el alcance de la arqueología debe limitarse estrictamente a las zonas de ruinas abandonadas; no se permite ninguna forma de escaneo o réplica de las zonas habitadas de la civilización viva.</p><p>Cuando el conocimiento descubierto por la arqueología se retorna y publica, debe respetarse la sensibilidad cultural de la civilización objetivo. Si los hallazgos arqueológicos involucran reliquias sagradas religiosas, restos ancestrales o tabúes culturales de la civilización objetivo, la información pertinente debe pasar por una revisión de sensibilidad cultural del Comité de Ética Transplanar antes de su publicación, y los detalles sensibles deben difuminarse cuando sea necesario.</p><h3 id="_3-2-normas-eticas-para-el-escenario-de-comunicacion" tabindex="-1">3.2 Normas Éticas para el Escenario de Comunicación <a class="header-anchor" href="#_3-2-normas-eticas-para-el-escenario-de-comunicacion" aria-label="Permalink to &quot;3.2 Normas Éticas para el Escenario de Comunicación&quot;">​</a></h3><p>La comunicación transplanar es un medio de intercambio directo con la civilización objetivo, y el núcleo de sus normas éticas es la &quot;sinceridad y el respeto&quot;. El contenido de la comunicación debe ser veraz, sin proporcionar deliberadamente información falsa o propaganda engañosa; el tono de la comunicación debe ser igualitario, sin tratar con condescendencia a las civilizaciones de menor nivel de desarrollo; los temas de la comunicación deben contar con el consentimiento de la civilización objetivo, sin imponer por la fuerza la ideología o las creencias religiosas del propio plano.</p><p>Al establecer comunicación por primera vez con una civilización desconocida, debe seguirse la norma de &quot;contacto gradual&quot;: primero enviar señales matemáticas y físicas neutras para confirmar el nivel de inteligencia y la capacidad de comunicación de la otra parte, luego ampliar gradualmente el alcance del intercambio sobre la base de la respuesta de la otra parte; no deben enviarse informaciones culturales o técnicas complejas durante el primer contacto.</p><h3 id="_3-3-normas-eticas-para-el-escenario-comercial" tabindex="-1">3.3 Normas Éticas para el Escenario Comercial <a class="header-anchor" href="#_3-3-normas-eticas-para-el-escenario-comercial" aria-label="Permalink to &quot;3.3 Normas Éticas para el Escenario Comercial&quot;">​</a></h3><p>El núcleo de las normas éticas del comercio transplanar es la &quot;equidad y la sostenibilidad&quot;. El comercio debe basarse en el consentimiento voluntario de ambas partes, sin utilizar la asimetría de información o las ventajas tecnológicas para transacciones coercitivas; los precios comerciales deben ser justos, sin fijación de precios depredadora; las mercancías comerciales no deben incluir contenidos que puedan causar un shock social o daños ecológicos a la civilización objetivo.</p><p>Se debe prestar especial atención a que el comercio transplanar de tecnología de cultivo y armas de alta energía está sujeto a las restricciones éticas más estrictas. Exportar tecnología de cultivo de alto nivel a civilizaciones de menor nivel de desarrollo puede provocar el desequilibrio de sus estructuras sociales y la intensificación de sus conflictos internos; exportar armas puede desencadenar directamente guerras. Por lo tanto, estos dos tipos de comercio están prohibidos en principio, y solo pueden realizarse tras la aprobación de una sesión plenaria de la Asamblea Legislativa del Ancla en circunstancias extremadamente especiales.</p><h3 id="_3-4-normas-eticas-para-el-escenario-de-intervencion-de-emergencia" tabindex="-1">3.4 Normas Éticas para el Escenario de Intervención de Emergencia <a class="header-anchor" href="#_3-4-normas-eticas-para-el-escenario-de-intervencion-de-emergencia" aria-label="Permalink to &quot;3.4 Normas Éticas para el Escenario de Intervención de Emergencia&quot;">​</a></h3><p>Cuando la civilización del plano objetivo enfrenta una crisis de nivel de extinción (como un impacto de asteroide, una superplaga, un colapso de las leyes), la Civilización Simbiótica del Ancla puede realizar una intervención humanitaria. Pero incluso en tales situaciones de emergencia, deben observarse las siguientes normas éticas:</p><ul><li>Antes de la intervención, debe obtenerse en la medida de lo posible el consentimiento informado de la civilización objetivo; si la civilización objetivo no puede responder eficazmente debido a la crisis, el Comité de Ética Transplanar emite en su nombre un juicio de &quot;consentimiento presunto&quot;</li><li>Los medios de intervención deben elegir el esquema de menor impacto sobre la civilización objetivo, priorizando la intervención indirecta (como modificar la órbita del asteroide) sobre la intervención directa (como llegar directamente para el rescate)</li><li>Durante la intervención, no debe aprovecharse la ocasión para obtener los recursos o la tecnología de la civilización objetivo</li><li>Tras finalizar la intervención, se exige la retirada inmediata, sin dejar presencia permanente en el plano objetivo</li><li>Posteriormente, debe presentarse un informe completo de la intervención al Comité de Ética Transplanar para su revisión ética</li></ul><h2 id="iv-supervision-etica-y-tratamiento-de-violaciones" tabindex="-1">IV. Supervisión Ética y Tratamiento de Violaciones <a class="header-anchor" href="#iv-supervision-etica-y-tratamiento-de-violaciones" aria-label="Permalink to &quot;IV. Supervisión Ética y Tratamiento de Violaciones&quot;">​</a></h2><p>El Universo Hengyuan estableció el &quot;Comité de Ética Transplanar&quot; como institución independiente de supervisión ética, responsable de formular e interpretar las Normas Éticas Transplanar, aprobar proyectos de interacción transplanar de alto riesgo, recibir denuncias de violaciones éticas e investigar y juzgar las violaciones. El comité está compuesto por eticistas, juristas, científicos y representantes de civilizaciones de diferentes razas y diferentes trayectorias profesionales, garantizando la diversidad y la imparcialidad de las decisiones.</p><p>Para los comportamientos que violan las Normas Éticas Transplanar, según la gravedad de las circunstancias, las medidas de tratamiento incluyen: advertencia verbal, reprimenda por escrito, suspensión de las calificaciones de interacción transplanar, revocación del permiso de travesía, multas, prisión y, en casos extremos, el &quot;exilio planar&quot; (privación del derecho a residir en los planos principales del Universo Hengyuan). Todos los resultados del tratamiento de violaciones éticas se registran en los archivos éticos personales u organizacionales, conservados de forma permanente.</p><h2 id="conclusion" tabindex="-1">Conclusión <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusión&quot;">​</a></h2><p>Las Normas Éticas Transplanar son una manifestación concentrada de la altura moral de la Civilización Simbiótica del Ancla. No solo prescriben &quot;qué no debe hacerse&quot;, sino que también proclaman &quot;en qué debe uno convertirse&quot;: una civilización verdaderamente grande no es la que ha conquistado a muchas otras civilizaciones, sino la que ha respetado la subjetividad de muchas otras civilizaciones. En el camino del Universo Hengyuan hacia la simbiosis interestelar, las Normas Éticas Transplanar serán siempre el faro moral que guía la dirección.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>81-位面穿梭规则 (Las Reglas de Travesía Transplanar)</li><li>87-仅回传知识原则 (El Principio de Retorno de Solo Conocimiento)</li><li>04-反掠夺主义核心论纲 (Tesis central del antidepredacionismo)</li></ul>',30)])])}const v=e(s,[["render",r]]);export{m as __pageData,v as default};
